import math

state = 'pull_forward'
fwd_start_t = None

def control(obs):
    global state, fwd_start_t
    t = obs.get('t', 0.0)
    status = obs.get('status', '')
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch_deg = obs.get('hitch_deg', 0.0)

    if status == 'PINNED' or hold_s > 0:
        fwd_start_t = None
        return (-25.0, 0.0, 0.0)

    if state == 'pull_forward':
        if fwd_start_t is None:
            fwd_start_t = t
        elapsed = t - fwd_start_t
        if elapsed < 2.5:
            return (-25.0, 1.2, 0.0)
        else:
            state = 'reversing'

    cycle = int(t * 0.8) % 3
    if cycle == 0:
        look = 64.0
    elif cycle == 1:
        look = -64.0
    else:
        look = 170.0

    views = obs.get('views', {})
    pts = []
    for vname, v in views.items():
        orig = v.get('origin', [0.0, 0.0])
        for b_deg, d in v.get('walls', []):
            rad = math.radians(b_deg)
            px = orig[0] + d * math.cos(rad)
            py = orig[1] + d * math.sin(rad)
            pts.append((px, py))

    rig = obs.get('rig', {})
    tr_rear = rig.get('trailer_rear', [-6.3, 0.0])
    tr_x, tr_y = tr_rear[0], tr_rear[1]

    left_dist = 99.0
    right_dist = 99.0

    for px, py in pts:
        dx = px - tr_x
        dy = py - tr_y
        if -4.0 < dx < 2.5:
            if dy > 0:
                left_dist = min(left_dist, dy)
            else:
                right_dist = min(right_dist, -dy)

    target_hitch = 0.0
    if left_dist < 90.0 and right_dist < 90.0:
        lat_err = left_dist - right_dist
        target_hitch = max(-18.0, min(18.0, -lat_err * 12.0))
    elif left_dist < 1.6:
        target_hitch = 14.0
    elif right_dist < 1.6:
        target_hitch = -14.0

    hitch_err = hitch_deg - target_hitch
    steer = 2.8 * hitch_err
    steer = max(-45.0, min(45.0, steer))

    speed = -0.65
    return (steer, speed, look)

