    min_left_clearance = 99.0
    for b, d in walls:
        rel = (b - (180.0 - hitch) + 180.0) % 360.0 - 180.0
        lat = d * math.sin(math.radians(rel))
        dist_back = d * math.cos(math.radians(rel))
        if -1.0 < dist_back < 10.0:
            if lat > 0:
                min_left_clearance = min(min_left_clearance, lat)
            else:
